namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "English", Abbreviation = "ENG" },
        new() { Id = 4, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses;

    public CatalogService()
    {
        _courses =
        [
            new()
            {
                Id = 1, CourseCode = "CS101", Title = "Introduction to Programming",
                Description = "A foundational course covering programming concepts using C#. Topics include variables, control flow, data structures, and object-oriented design principles.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of teaching experience and specializes in programming pedagogy and software engineering education.",
                IsFeatured = true
            },
            new()
            {
                Id = 2, CourseCode = "CS301", Title = "Data Structures & Algorithms",
                Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques including divide-and-conquer, dynamic programming, and greedy algorithms.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor is a published researcher in algorithm optimization with industry experience at major tech companies.",
                IsFeatured = true
            },
            new()
            {
                Id = 3, CourseCode = "CS420", Title = "Machine Learning",
                Description = "Introduction to machine learning techniques including supervised learning, unsupervised learning, neural networks, and practical applications using Python.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez leads the university's AI research lab and has published over 40 papers in top ML conferences.",
                IsFeatured = false
            },
            new()
            {
                Id = 4, CourseCode = "MATH201", Title = "Linear Algebra",
                Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Prof. Robert Kim", InstructorBio = "Prof. Kim is an award-winning educator known for making abstract algebra accessible and engaging.",
                IsFeatured = true
            },
            new()
            {
                Id = 5, CourseCode = "MATH305", Title = "Probability & Statistics",
                Description = "Probability theory, random variables, statistical inference, hypothesis testing, and regression analysis.",
                Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Dr. Emily Watson", InstructorBio = "Dr. Watson combines academic rigor with real-world examples from her consulting work in biostatistics.",
                IsFeatured = false
            },
            new()
            {
                Id = 6, CourseCode = "ENG102", Title = "Academic Writing",
                Description = "Develops skills in analytical reading, argumentation, research methods, and clear academic prose across disciplines.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "English",
                InstructorName = "Prof. Diana Torres", InstructorBio = "Prof. Torres has authored two textbooks on composition and mentors students in the university writing center.",
                IsFeatured = false
            },
            new()
            {
                Id = 7, CourseCode = "ENG350", Title = "Modern American Literature",
                Description = "Survey of American literature from 1900 to present, exploring themes of identity, modernity, and cultural change.",
                Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 3, DepartmentName = "English",
                InstructorName = "Dr. Alan Hughes", InstructorBio = "Dr. Hughes specializes in 20th-century American fiction and has received multiple teaching excellence awards.",
                IsFeatured = true
            },
            new()
            {
                Id = 8, CourseCode = "PHYS101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", DepartmentId = 4, DepartmentName = "Physics",
                InstructorName = "Dr. Kevin Park", InstructorBio = "Dr. Park brings enthusiasm for experimental physics and has designed innovative lab curricula adopted by peer institutions.",
                IsFeatured = false
            },
            new()
            {
                Id = 9, CourseCode = "PHYS305", Title = "Quantum Mechanics",
                Description = "Wave functions, Schrödinger equation, quantum states, measurement theory, and applications to atomic and molecular systems.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 4, DepartmentName = "Physics",
                InstructorName = "Dr. Natasha Volkov", InstructorBio = "Dr. Volkov is a theoretical physicist whose research focuses on quantum information and entanglement.",
                IsFeatured = false
            },
            new()
            {
                Id = 10, CourseCode = "HIST210", Title = "World History: 1500–Present",
                Description = "Global perspectives on colonialism, industrialization, world wars, decolonization, and globalization.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 5, DepartmentName = "History",
                InstructorName = "Prof. Marcus Johnson", InstructorBio = "Prof. Johnson is a historian of global trade networks and has conducted fieldwork on four continents.",
                IsFeatured = false
            },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.OrderBy(c => c.CourseCode).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

