@page "/"
@inject CatalogService Catalog

<PageTitle>Home — University Course Catalog</PageTitle>

<section class="hero">
    <h1>Welcome to the Course Catalog</h1>
    <p>Explore departments, discover courses, and submit your enrollment request.</p>
    <a href="/courses" class="btn btn-primary">Browse All Courses</a>
</section>

<section class="section">
    <h2>Featured Courses</h2>
    <div class="card-grid">
        @foreach (var course in _featured)
        {
            <div class="card">
