                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Instructor</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in _courses)
            {
                <tr>
                    <td><code>@course.CourseCode</code></td>
                    <td><a href="/courses/@course.Id">@course.Title</a></td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.InstructorName</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Course> _courses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _departments = Catalog.GetDepartments();
        _courses = Catalog.GetCourses(Search, DepartmentId);
    }
}

@page "/courses/{Id:int}"
@inject CatalogService Catalog

@if (_course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist. <a href="/courses">Return to catalog</a>.</p>
}
else
{
    <PageTitle>@_course.Title — University Course Catalog</PageTitle>

    <nav class="breadcrumb">
        <a href="/courses">Courses</a> &rsaquo;
        <a href="/courses?departmentId=@_course.DepartmentId">@_course.DepartmentName</a> &rsaquo;
        <span>@_course.CourseCode</span>
    </nav>

    <article class="course-detail">
        <header>
            <h1>@_course.Title</h1>
            <p class="course-meta">
                <code>@_course.CourseCode</code> · @_course.Credits credits · @_course.DepartmentName
            </p>
        </header>

        <section class="detail-section">
            <h2>Description</h2>
            <p>@_course.Description</p>
        </section>

        <section class="detail-section">
            <h2>Schedule</h2>
            <p>@_course.Schedule</p>
        </section>

        <section class="detail-section">
            <h2>Instructor</h2>
            <p><strong>@_course.InstructorName</strong></p>
            <p>@_course.InstructorBio</p>
        </section>

        <div class="detail-actions">
            <a href="/enroll?courseId=@_course.Id" class="btn btn-primary">Request Enrollment</a>
            <a href="/courses" class="btn btn-secondary">Back to Catalog</a>
        </div>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        _course = Catalog.GetCourse(Id);
    }
}

@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h2>Request Submitted!</h2>
        <p>Thank you, <strong>@_model.FullName</strong>. Your enrollment request for
        <strong>@(_selectedCourse?.Title ?? "the selected course")</strong> has been received.
        You will be notified by email once it is processed.</p>
        <a href="/courses" class="btn btn-primary">Back to Catalog</a>
    </div>
}
else
{
    <EditForm method="post" Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="form-group">
            <label for="fullName">Full Name</label>
            <InputText id="fullName" @bind-Value="_model.FullName" class="input" />
            <ValidationMessage For="() => _model.FullName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="_model.StudentId" class="input" placeholder="e.g., CS123456" />
            <ValidationMessage For="() => _model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="_model.CourseId" class="input">
                <option value="0">— Select a course —</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id">@course.CourseCode — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> _courses = [];
    private bool _submitted;
    private Course? _selectedCourse;

    protected override void OnInitialized()
    {
        _courses = Catalog.GetCourses();

        if (CourseId.HasValue && _model.CourseId == 0)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        _selectedCourse = Catalog.GetCourse(_model.CourseId);
        _submitted = true;
    }
}

